package br.com.weg.workshop.auth.service; import br.com.weg.workshop.user.domain.UserEntity; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service;
@Service class SmtpPasswordResetMailService implements PasswordResetMailService {private final JavaMailSender mail; SmtpPasswordResetMailService(JavaMailSender mail){this.mail=mail;} public void send(UserEntity u,String token){var m=new SimpleMailMessage();m.setTo(u.getEmail());m.setSubject("Password reset");m.setText("Use this password reset token: "+token);mail.send(m);}}
